-- --------------------------------------------------------------------------------------------------------------
-- 1. 15 missions (catalog 15 to 29), every one a draft
insert into public.action_missions
  (id, campaign_id, title, description, domain, difficulty, base_points, proof_required, verification_mode,
   skills, capacity, status, starts_at, ends_at, kind, discovery_category)
select v.id, null, v.title, v.description, v.domain, v.difficulty, v.base_points, true, v.verification_mode,
       v.skills, null, 'draft', null, null, 'civic', v.discovery_category
  from (values
    ('feec02fd-a269-5c00-94ac-c16737ad7546'::uuid, -- drawdown-improve-cement-production
     'Ask your city if it buys lower-carbon concrete',
     'Concrete for sidewalks, schools and roads is often bought by local governments. Send a short, polite question in your own words to your city or county''s public works or purchasing office, or ask during a public comment period, about whether its rules allow or encourage lower-carbon concrete. Post your question and any reply, with names and contact details hidden.',
     'advocacy', 'explore', 2, 100, 'review', array['policy-analysis','writing']::text[]),
    ('940ee6f3-0ff8-528c-bc73-30f4a3a03d29'::uuid, -- drawdown-increase-centralized-composting
     'Map the food scrap drop-off spots near you',
     'Find out whether your city or local services collect food scraps for composting, through curbside pickup, drop-off points or farmers markets. Make a simple map or list with locations, hours and what''s accepted, and share it with neighbors. If nothing exists, send a polite question in your own words to your council member instead and post that, with names and contact details hidden.',
     'community', 'help', 1, 100, 'review', array['research','mapping']::text[]),
    ('39c075dc-ce16-5321-b1d7-5b75b916a3cb'::uuid, -- drawdown-deploy-industrial-green-hydrogen
     'Look up hydrogen projects planned in your region',
     'Search official sources, such as your energy department, regional development agency or permitting portals, for hydrogen projects planned near you, and note whether they would make hydrogen with renewable electricity. Write a short, neutral summary with links, including any public meetings or comment periods. Post it.',
     'research', 'explore', 2, 100, 'review', array['research','policy-analysis']::text[]),
    ('5ce73068-1f93-55dd-a858-c36c2ebeb612'::uuid, -- drawdown-improve-landfill-management
     'Find out which landfill takes your trash',
     'Use your local waste agency''s website to learn where your household trash ends up, then look for public information on whether that landfill collects the gas it gives off. Write a short summary with links and share it with neighbors. If the information isn''t public, send a polite question to the agency and post that.',
     'research', 'explore', 2, 100, 'review', array['research','writing']::text[]),
    ('34dcd492-e437-500b-8818-fd9dfaa3fbbc'::uuid, -- drawdown-increase-recycling
     'Make a recycling sign for your building',
     'Get your area''s official recycling rules and turn them into a clear, one-page sign showing what goes in the recycling for metals, paper and cardboard, plastics and glass, with pictures if you can. Ask your building manager, school or community center for permission to post it. Post a photo of the sign in place.',
     'community', 'create', 1, 100, 'review', array['design','community']::text[]),
    ('69a6d95a-447b-5cdc-9d60-064b8dc01d6f'::uuid, -- drawdown-increase-carpooling
     'Organize a carpool for one regular trip',
     'Pick one regular trip that several people you know make, such as getting to work, school, practice or worship, and set up a simple sign-up sheet or group chat so people can share rides. Agree on times, public meeting spots and how you''ll handle changes; if the riders are children, set it up only among their parents or guardians. Post a photo of your sign-up sheet or schedule with names and contact details hidden.',
     'community', 'help', 2, 100, 'review', array['organizing','community']::text[]),
    ('6b7e9acb-e697-56e8-beb4-417333d2c5db'::uuid, -- drawdown-mobilize-electric-bicycles
     'Make a guide to e-bike rules where you live',
     'Find the official rules for electric bicycles in your city, state or country, such as where they can be ridden, age limits and helmet rules, plus any official e-bike share or lending program. Make a one-page guide with links to the official sources and share it with a neighborhood or school group. Post a photo or link of your guide.',
     'education', 'create', 2, 100, 'review', array['research','writing']::text[]),
    ('febe45f0-f1d6-57ef-a5f4-73ed7e4985c4'::uuid, -- drawdown-mobilize-electric-cars
     'Map the public car chargers in your neighborhood',
     'Use a free public charging station map, such as one run by your government, to find electric car chargers near you. Mark them on a simple map and note which neighborhoods, apartment areas or main streets have few or none. Post your map with the source.',
     'research', 'explore', 1, 100, 'review', array['mapping','research']::text[]),
    ('0b3adca4-63f1-50aa-a3d8-1fdd8426d787'::uuid, -- drawdown-mobilize-electric-seated-scooters-motorcycles
     'Ask a local scooter shop about electric models',
     'Visit a motorcycle or scooter shop during business hours and ask the staff which electric models people ask about, what riders like, and what holds them back. Take notes, with a photo only if they agree, then write a short summary. Post it.',
     'business', 'explore', 2, 100, 'review', array['interviewing','writing']::text[]),
    ('e2aa8ccd-9bc3-5941-8e81-3d3cd8cbb57c'::uuid, -- drawdown-mobilize-hybrid-cars
     'Compare your car''s fuel economy with a hybrid',
     'Look up the official fuel economy rating for the car your household uses, or one you see often, on your government''s fuel economy website, and compare it with a hybrid version or a similar hybrid model. Make a simple side-by-side chart. Post a photo of your chart and the source.',
     'research', 'explore', 1, 100, 'review', array['research','data-analysis']::text[]),
    ('7fd3053d-e1af-5477-a656-1a38e6569588'::uuid, -- drawdown-improve-nonmotorized-transportation
     'Do a walk audit of a route to a school or park',
     'Walk a short route that kids or neighbors use to reach a school, park or library, and note anything that makes walking or biking hard, such as missing sidewalks, broken curb ramps or long waits at crossings. Report the issues through your city''s official service request or feedback channel. Post your notes and a screenshot of your report.',
     'advocacy', 'explore', 1, 100, 'review', array['observation','writing']::text[]),
    ('a87e5275-c212-51bf-8650-22af893a7fd0'::uuid, -- drawdown-enhance-public-transit
     'Rate the bus stops near you and report back',
     'Visit a few bus or tram stops near you and note what each one has, such as a shelter, a bench, lighting, a posted schedule, and a smooth path for wheelchairs and strollers. Send a short, polite summary to your transit agency through its official feedback channel. Post your notes and the message you sent.',
     'advocacy', 'explore', 1, 100, 'review', array['observation','writing']::text[]),
    ('8b493fa5-e6c6-5b83-8ac7-83741aa8882d'::uuid, -- drawdown-reduce-crop-residue-burning
     'Explain what farmers can do with leftover stalks',
     'After harvest, fields are left with stalks, leaves and husks that are sometimes burned. Using reliable sources, find out other things farmers do with these leftovers, such as leaving them as mulch or using them for animal bedding, and make a short explainer post, poster or video. Post it with your sources.',
     'education', 'create', 2, 100, 'review', array['research','teaching']::text[]),
    ('e86c2226-e09f-59d4-90e6-3a8106cf4c2c'::uuid, -- drawdown-improve-diets
     'Share a plant-rich family recipe with neighbors',
     'Cook a favorite dish built mostly on beans, grains, vegetables or other plant foods, maybe one from your family or culture, and write it up as a simple recipe card. Share it with neighbors or at a potluck, listing the main ingredients so people with allergies can check. Post a photo of the dish and the card.',
     'community', 'create', 1, 100, 'review', array['cooking','writing']::text[]),
    ('ed9a7f1a-93f5-5ed7-852e-e99ed689ff36'::uuid, -- drawdown-reduce-food-loss-waste
     'Track a week of food waste at home',
     'For one week, keep a simple log of food your household throws away, what it was and why, such as forgotten leftovers or buying too much. At the end of the week, pick one easy change to try and share it with friends or neighbors. Post a photo of your log and your chosen change.',
     'research', 'explore', 1, 100, 'review', array['observation','data-analysis']::text[])
  ) as v(id, title, description, domain, discovery_category, difficulty, base_points, verification_mode, skills)
on conflict (id) do nothing;

