-- 2. their 15 details rows: proof hint, safety note, credit, quotation, source, licence
insert into public.action_mission_details
  (mission_id, catalog, slug, proof_hint, safety_note, credit_line, about, about_credit, source_url,
   license_name, license_url, doi)
select v.mission_id, 'drawdown', v.slug, v.proof_hint, v.safety_note, v.credit_line, v.about, v.about_credit,
       v.source_url, v.license_name, v.license_url, v.doi
  from (values
    ('feec02fd-a269-5c00-94ac-c16737ad7546'::uuid, 'drawdown-improve-cement-production',
     'A screenshot of your question and any reply, with names and contact details hidden.',
     'Ask through official public channels, and don''t visit cement plants or construction sites.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/improve-cement-production), used with permission; assessment "Improve Cement Production- Solution Assessment Spreadsheet" by Sarah Gleeson, https://doi.org/10.5281/zenodo.21231071, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Cement is a key ingredient of concrete, a manufactured material used in massive quantities around the world. Cement production generates high CO₂ emissions from the production of clinker, a binding ingredient. These emissions come from not only the chemical reaction that produces clinker, but also burning fossil fuels to provide heat for this reaction.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/improve-cement-production', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21231071'),
    ('940ee6f3-0ff8-528c-bc73-30f4a3a03d29'::uuid, 'drawdown-increase-centralized-composting',
     'Your map or list, or a screenshot of your question to the council with names and contact details hidden.',
     'Use official information, follow drop-off rules, and never leave food scraps where they aren''t accepted.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/increase-centralized-composting), used with permission; assessment "Increase Centralized Composting- Solution Assessment Spreadsheet" by Megan Matthews and Sarah Gleeson, https://doi.org/10.5281/zenodo.21246147, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'A composting system diverts organic waste (OW) from landfills, reducing the production of methane and other GHG emissions. OW is defined as the combination of food waste and green waste, composed of yard and garden trimmings. Composting transforms it into a nutrient-rich soil supplement.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/increase-centralized-composting', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21246147'),
    ('39c075dc-ce16-5321-b1d7-5b75b916a3cb'::uuid, 'drawdown-deploy-industrial-green-hydrogen',
     'Your summary with links to official sources.',
     'Use public records and official meetings only, and don''t visit industrial sites.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/deploy-industrial-green-hydrogen), used with permission; assessment "Deploy Industrial Green Hydrogen- Solution Assessment Spreadsheet" by Heather McDiarmid and Nina F. Farac, https://doi.org/10.5281/zenodo.21246254, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'In this solution, green hydrogen replaces fossil fuel–based hydrogen for use as a feedstock in the production of more complex molecules such as ammonia for fertilizers and methanol for the production of other commodity chemicals. Green hydrogen production in this solution uses on-site renewable electricity or off-site renewable electricity that directly supplies the facility.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/deploy-industrial-green-hydrogen', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21246254'),
    ('5ce73068-1f93-55dd-a858-c36c2ebeb612'::uuid, 'drawdown-improve-landfill-management',
     'Your summary with source links, or a screenshot of your question with names and contact details hidden.',
     'Research online or ask the agency; never enter landfill grounds.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/improve-landfill-management), used with permission; assessment "Improve Landfill Management- Solution Assessment Spreadsheet" by Jason Lam and Henry Igugu, https://doi.org/10.5281/zenodo.21231060, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Landfill management is the process of reducing methane emissions from landfill gas (LFG). As bacteria break down organic waste in an environment without oxygen, they produce methane and release it into the atmosphere if there are no controls in place. This solution focuses on two methane abatement strategies: 1) methane capture/use/destruction and 2) biocovers.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/improve-landfill-management', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21231060'),
    ('34dcd492-e437-500b-8818-fd9dfaa3fbbc'::uuid, 'drawdown-increase-recycling',
     'A photo of the sign posted where you have permission, framed so no names, unit numbers, addresses or people show.',
     'Follow your local official rules, post only where you have permission, and don''t sort through other people''s bins.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/increase-recycling), used with permission; assessment "Increase Recycling- Solution Assessment Spreadsheet" by Nina F. Farac and Megan Matthews, https://doi.org/10.5281/zenodo.21246177, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Recycling is a mechanical process that repurposes waste into new products without altering their chemical structure. This solution focuses on four common waste types: metals, paper and cardboard, plastics, and glass. It reduces GHG emissions by minimizing reliance on energy-intensive primary material production, reducing demand for raw materials, and diverting paper from landfills, where decomposition can produce methane.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/increase-recycling', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21246177'),
    ('69a6d95a-447b-5cdc-9d60-064b8dc01d6f'::uuid, 'drawdown-increase-carpooling',
     'A photo of the sign-up sheet or schedule with names, phone numbers and addresses hidden.',
     'Share rides only with people you know or trust and with licensed, insured drivers, make sure everyone wears a seat belt and children ride in the car seats the law requires, let only parents or guardians decide who drives their children, and keep contact details private.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/increase-carpooling), used with permission; assessment "Increase Carpooling- Solution Assessment Spreadsheet" by Heather Jones and Heather McDiarmid, https://doi.org/10.5281/zenodo.21246159, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Carpooling entails increasing the occupancy of passenger cars, including taxis, pickup trucks, motorhomes, passenger vans and other such vehicles but not including two- or three-wheeled, freight, public transit, or commercial vehicles, such as buses, heavy trucks, and commercial vans. It replaces the practice of driving alone.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/increase-carpooling', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21246159'),
    ('6b7e9acb-e697-56e8-beb4-417333d2c5db'::uuid, 'drawdown-mobilize-electric-bicycles',
     'A photo or link to your guide with official sources listed.',
     'Quote and link the official rules rather than giving your own legal interpretation, and if you ride, wear a helmet and follow traffic laws.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/mobilize-electric-bicycles), used with permission; assessment "Mobilize Electric Bicycles- Solution Assessment Spreadsheet" by Cameron Roberts and Zoltan Nagy, https://doi.org/10.5281/zenodo.21231092, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'We define the Mobilize Electric Bicycles solution as increased travel by bicycles that have an electric motor to supplement the effort of the rider, but require the rider to turn the pedals to activate the motor.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/mobilize-electric-bicycles', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21231092'),
    ('febe45f0-f1d6-57ef-a5f4-73ed7e4985c4'::uuid, 'drawdown-mobilize-electric-cars',
     'Your map with the source named.',
     'Use public maps, and if you visit a charger, don''t block it or touch other people''s cars or cables.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/mobilize-electric-cars), used with permission; assessment "Mobilize Electric Cars- Solution Assessment Spreadsheet" by Cameron Roberts and Jason Lam, https://doi.org/10.5281/zenodo.21231076, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Electric cars are four-wheeled passenger cars that run on electricity, usually from the electricity grid and stored in onboard batteries (i.e., not including fuel cell electric cars). This definition includes electric pickup trucks, motorhomes, and other such vehicles. It does not include two-wheeled vehicles or hybrid cars (which combine an electric motor with a gasoline or diesel engine).',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/mobilize-electric-cars', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21231076'),
    ('0b3adca4-63f1-50aa-a3d8-1fdd8426d787'::uuid, 'drawdown-mobilize-electric-seated-scooters-motorcycles',
     'A short summary of the conversation, with photos only if you had permission.',
     'Ask permission before recording, don''t test-ride anything for this mission, and share names only with consent.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/mobilize-electric-seated-scooters-motorcycles), used with permission; assessment "Mobilize Electric Scooters and Motorcycles- Solution Assessment Spreadsheet" by Heather Jones and Nina F. Farac, https://doi.org/10.5281/zenodo.23375984, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'Electric scooters and motorcycles are battery-powered two- and three-wheeled vehicles that provide low-emissions mobility. This category of transport includes electric mopeds, motorbikes, seated motor scooters, motorcycles, and three-wheel vehicles, such as e-rickshaws and e-tuk-tuks.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/mobilize-electric-seated-scooters-motorcycles', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.23375984'),
    ('e2aa8ccd-9bc3-5941-8e81-3d3cd8cbb57c'::uuid, 'drawdown-mobilize-hybrid-cars',
     'A photo of your chart with the official source named.',
     'Use official ratings, and don''t give anyone buying or financing advice.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/mobilize-hybrid-cars), used with permission; assessment "Mobilize Hybrid Cars- Solution Assessment Spreadsheet" by Heather Jones and Zoltan Nagy, https://doi.org/10.5281/zenodo.20865760, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'The Mobilize Hybrid Cars solution entails shifting trips from fossil fuel–powered internal combustion engine (ICE) cars to more efficient, lower emitting hybrid cars. Hybrid cars include hybrid electric cars (HEVs) and plug-in hybrid electric cars (PHEVs). They are four-wheeled passenger cars that combine an ICE with an electric motor and battery to improve fuel efficiency and reduce emissions.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/mobilize-hybrid-cars', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.20865760'),
    ('7fd3053d-e1af-5477-a656-1a38e6569588'::uuid, 'drawdown-improve-nonmotorized-transportation',
     'Your notes and a screenshot of your report with personal details hidden.',
     'Walk in daylight, stay on sidewalks and crossings, note hazards without stepping into traffic, and keep children and other people''s faces out of any photos.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/improve-nonmotorized-transportation), used with permission; assessment "Improve Nonmotorized Transportation- Solution Assessment Spreadsheet" by Cameron Roberts and Heather Jones, https://doi.org/10.5281/zenodo.21231018, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'We define Improve Nonmotorized Transportation as increasing any form of travel that does not use a motor or engine. In theory, this includes a huge range of transportation modes, including horses, cross-country skis, sailboats, hand-operated rickshaws, and animal-drawn carriages. In practice, pedestrian travel and cycling account for most nonmotorized utilitarian passenger travel.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/improve-nonmotorized-transportation', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21231018'),
    ('a87e5275-c212-51bf-8650-22af893a7fd0'::uuid, 'drawdown-enhance-public-transit',
     'Your notes or photos of the stops and a copy of your feedback message, with your name and contact details hidden.',
     'Visit in daylight, stay on the sidewalk and clear of traffic, and don''t photograph riders'' faces.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/enhance-public-transit), used with permission; assessment "Enhance Public Transit- Solution Assessment Spreadsheet" by Cameron Roberts and Heather Jones, https://doi.org/10.5281/zenodo.21230992, licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/). Adapted: the mission wording is original.',
     'We define the Enhance Public Transit solution as increasing the use of any form of passenger transportation that uses publicly available vehicles (e.g., buses, streetcars, subways, commuter trains, and ferries) operating along fixed routes.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/enhance-public-transit', 'CC BY 4.0', 'https://creativecommons.org/licenses/by/4.0/', 'https://doi.org/10.5281/zenodo.21230992'),
    ('8b493fa5-e6c6-5b83-8ac7-83741aa8882d'::uuid, 'drawdown-reduce-crop-residue-burning',
     'A link or photo of your explainer with sources listed.',
     'Research and explain only; never set or go near field fires.',
     'Solution summary from Project Drawdown (https://drawdown.org/explorer/reduce-crop-residue-burning), used with permission. Adapted: the mission wording is original.',
     'This solution avoids the burning of crop residues through the adoption of lower-emission options including straw balers, no-till seeders that can plant through residues, and developing markets for residue products. Some promising new techniques are also under development that could further increase future adoption and effectiveness of this solution.',
     'Solution summary © Project Drawdown, used with permission.',
     'https://drawdown.org/explorer/reduce-crop-residue-burning', null, null, null),
    ('e86c2226-e09f-59d4-90e6-3a8106cf4c2c'::uuid, 'drawdown-improve-diets',
